namespace ExosphereSimulation.Tests;

using System.Text.Json;
using Exosphere.Simulation.Environment;
using Xunit;
using Xunit.Abstractions;

/// <summary>
/// Environment plan E1.1: UTC, TAI, TT and TDB against the IAU SOFA library (ERFA) at 113
/// instants from 1961 to 2035 (fixture generated by tools/envdata/fixtures/time_scales.py).
/// TAI and TT must agree to 1 µs (exact table arithmetic; the bound is double rounding of
/// ~10⁹ s); TDB to 10 µs, the published accuracy of the truncated Fairhead–Bretagnon series.
/// </summary>
public sealed class TimeScalesTests(ITestOutputHelper output)
{
    private const double TaiToleranceSeconds = 1e-6;
    private const double TdbToleranceSeconds = 10e-6;

    [Fact]
    public void ScalesMatchErfaFrom1961To2035()
    {
        var scales = TimeScales.LoadFromDataDirectory(DataDirectory());
        using var fixture = JsonDocument.Parse(File.ReadAllText(FixturePath()));
        double worstTai = 0.0, worstTdb = 0.0, worstSpice = 0.0, worstRoundTrip = 0.0;
        int count = 0;
        foreach (var instant in fixture.RootElement.GetProperty("instants").EnumerateArray())
        {
            var c = instant.GetProperty("utc").EnumerateArray().Select(e => e.GetDouble()).ToArray();
            double utc = TimeScales.UtcSecondsFromCalendar((int)c[0], (int)c[1], (int)c[2], (int)c[3], (int)c[4], c[5]);
            double tai = scales.UtcToTai(utc);
            double tt = TimeScales.TaiToTt(tai);
            double tdb = TimeScales.TtToTdb(tt);
            string note = instant.GetProperty("note").GetString()!;
            double taiError = System.Math.Abs(tai - instant.GetProperty("tai_s").GetDouble());
            double ttError = System.Math.Abs(tt - instant.GetProperty("tt_s").GetDouble());
            double tdbError = System.Math.Abs(tdb - instant.GetProperty("tdb_s").GetDouble());
            Assert.True(taiError <= TaiToleranceSeconds, $"{note}: TAI off by {taiError:E3} s");
            Assert.True(ttError <= TaiToleranceSeconds, $"{note}: TT off by {ttError:E3} s");
            Assert.True(tdbError <= TdbToleranceSeconds, $"{note}: TDB off by {tdbError:E3} s");
            worstTai = System.Math.Max(worstTai, System.Math.Max(taiError, ttError));
            worstTdb = System.Math.Max(worstTdb, tdbError);
            if (instant.TryGetProperty("spice_et_s", out var et))
                worstSpice = System.Math.Max(worstSpice, System.Math.Abs(tdb - et.GetDouble()));
            worstRoundTrip = System.Math.Max(worstRoundTrip, System.Math.Abs(scales.TdbToUtc(tdb) - utc));
            count++;
        }
        output.WriteLine($"{count} instants: TAI/TT {worstTai:E2} s, TDB {worstTdb:E2} s, " +
            $"SPICE ET (one-term TDB) {worstSpice:E2} s, TDB→UTC round trip {worstRoundTrip:E2} s");
        Assert.True(count >= 100);
        Assert.True(worstRoundTrip <= TaiToleranceSeconds, $"round trip {worstRoundTrip:E3} s");
    }

    [Fact]
    public void Apollo11LaunchEpoch()
    {
        // SP-238: launch 1969-07-16 13:32:00 UTC, in the 1968-02-01 rate row of the USNO table.
        var scales = TimeScales.LoadFromDataDirectory(DataDirectory());
        double utc = TimeScales.UtcSecondsFromCalendar(1969, 7, 16, 13, 32, 0.0);
        double mjd = 51544.5 + utc / 86400.0;
        double expected = 4.2131700 + (mjd - 39126.0) * 0.002592;
        Assert.Equal(expected, scales.TaiMinusUtc(utc), 12);
        Assert.InRange(scales.TaiMinusUtc(utc), 7.563, 7.564);
    }

    [Fact]
    public void RejectsInstantsBeforeUtcExisted()
    {
        var scales = TimeScales.LoadFromDataDirectory(DataDirectory());
        double before = TimeScales.UtcSecondsFromCalendar(1960, 12, 31, 23, 59, 59.0);
        Assert.Throws<ArgumentOutOfRangeException>(() => scales.TaiMinusUtc(before));
        Assert.Equal(TimeScales.UtcSecondsFromCalendar(1961, 1, 1, 0, 0, 0.0), scales.FirstUtcSeconds);
        Assert.Throws<ArgumentOutOfRangeException>(() =>
            TimeScales.UtcSecondsFromCalendar(1969, 7, 16, 13, 32, 60.0));
    }

    [Fact]
    public void ReaderRefusesACorruptedProduct()
    {
        string path = Path.Combine(DataDirectory(), "environment", "time", "tai_utc.bin");
        var blob = File.ReadAllBytes(path);
        Assert.Equal("tai_utc", EnvironmentProductFile.Parse(blob).Product);
        blob[^1] ^= 1;
        Assert.Throws<InvalidDataException>(() => EnvironmentProductFile.Parse(blob));
    }

    private static string Root()
    {
        var directory = new DirectoryInfo(Directory.GetCurrentDirectory());
        while (directory != null && !File.Exists(Path.Combine(directory.FullName, "ExosphereSimulation.sln")))
            directory = directory.Parent;
        return directory!.FullName;
    }

    private static string DataDirectory() => Path.Combine(Root(), "data");

    private static string FixturePath() =>
        Path.Combine(Root(), "ExosphereSimulation.Tests", "Fixtures", "environment", "time_scales.json");
}
